# -*- coding: utf-8 -*-
"""MANAPRINT — KAUKURA (création 2KEA) · maquette CANVA de Maeva (26/11/2026,
« kaukura_canva_8_A4_2 »). Reprise TELLE QUELLE : 12 billets / feuille A4 PAYSAGE
(3 colonnes x 4 rangées), traits de coupe en pointillés. Chaque billet : la raie manta, le
requin, les hibiscus, les frises (dessin de la maquette posé en pochoir net : en couleur,
MANAPRINT le repeint, les chiffres restent noirs), le titre KAUKURA, le N° et les 8 ovales.
RÈGLE (Maeva + cliente, 26/11) — 8 boules, UNE PAR DIZAINE, rangées en ZIGZAG
(haut, bas, haut, bas… de gauche à droite) :
   1-9 · 10-19 · 20-29 · 30-39 · 40-49 · 50-59 · 60-69 · 70-75   -> crieur 1 à 75.
   La plage est écrite en petit en haut de chaque ovale (26/11).
Chiffres de la maquette (gras, 25 pt), noirs.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""
import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 3, 4
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 280.6299, 148.8189
NOIR = colors.black
RAINBOW = ["#E53935", "#FB8C00", "#F9A825", "#43A047", "#00ACC1",
           "#1E88E5", "#3949AB", "#8E24AA", "#D81B60", "#6D4C41"]
POLICE_NUM, T_NUM = "Helvetica-Bold", 25
_HAUT, _BAS = 82.2756, 47.4094          # lignes de base : rangée du haut, rangée du bas
# les 8 ovales en zigzag : (centre x, ligne de base, plage)
BOULES = [(59.528, _HAUT, (1, 9)), (81.638, _BAS, (10, 19)), (103.748, _HAUT, (20, 29)),
          (125.858, _BAS, (30, 39)), (147.969, _HAUT, (40, 49)), (170.079, _BAS, (50, 59)),
          (192.189, _HAUT, (60, 69)), (214.299, _BAS, (70, 75))]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        t = tuple(rng.randint(a, b) for _x, _y, (a, b) in BOULES)
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _modele(c):
    if getattr(c, "_kaukura_modele", False):
        return
    import base64
    d = _DESSIN
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("KAUKURA_CANVA", 0, 0, CELL_W, CELL_H)
    _masque.poser(c, "KAUKURA_IMG", base64.b64decode(_PNG), 0, 0, CELL_W, CELL_H)
    c._code.append("q\n" + d + "\nQ")
    c.endForm()
    c._kaukura_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("KAUKURA_CANVA")
    c.saveState()                                   # le N°, écrit debout le long du bord gauche
    c.transform(0, -1, 1, 0, 10.20472, 123.3071)
    _txt(c, "N\u00b0 %05d" % (serie % 100000), 0, -1.8, "Helvetica", 5.5, colors.Color(.15, .15, .15))
    c.restoreState()
    for (x, y, (a, b)), n in zip(BOULES, nums):
        _txt(c, str(n), x, y - 2.8, POLICE_NUM, T_NUM, col, centre=True)
        _txt(c, "%d-%d" % (a, b), x, y + 18.9, "Helvetica-Bold", 5.2, NOIR, centre=True)   # la plage, en haut de l'ovale
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("KAUKURA")
    rng = random.Random(int(serie_start) * 100003 + 2611)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    col_imposee = None
    if couleur and couleur_perso:
        try:
            col_imposee = colors.HexColor(couleur_perso)
        except Exception:
            col_imposee = None

    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)

        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            col = (col_imposee or colors.HexColor(RAINBOW[serie % len(RAINBOW)])) if couleur else NOIR
            _billet(c, ox, oy, serie, _numeros(rng), col)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


